import 'package:material_ui/material_ui.dart';

import '../theme/app_colors.dart';
import '../theme/tokens.dart';

/// The classic raised-and-textured look: linen background, paper panels,
/// blue leather title bar, brushed steel tab bar, beveled buttons that sink
/// when pressed.
///
/// The textures are tileable overlays generated by tool/gen_textures.py:
/// white or black with varying alpha, so they work on any base colour in the
/// light and dark themes.
class Textures {
  Textures._();

  static const linen = 'assets/textures/linen.png';
  static const paper = 'assets/textures/paper.png';
  static const metal = 'assets/textures/metal.png';
  static const leather = 'assets/textures/leather.png';

  static const all = [linen, paper, metal, leather];

  /// Starts loading the textures before the first screen, so they do not
  /// pop in. Needs no BuildContext: the images stay in Flutter's image
  /// cache and the first paint finds them there.
  static void precache() {
    for (final t in all) {
      final stream = AssetImage(t).resolve(ImageConfiguration.empty);
      late final ImageStreamListener listener;
      void done() => stream.removeListener(listener);
      listener = ImageStreamListener(
        (_, _) => done(),
        onError: (_, _) => done(),
      );
      stream.addListener(listener);
    }
  }

  static DecorationImage image(String asset, {double opacity = 1}) =>
      DecorationImage(
        image: AssetImage(asset),
        repeat: ImageRepeat.repeat,
        opacity: opacity,
        filterQuality: FilterQuality.medium,
      );
}

/// A soft drop shadow, the same everywhere, so every raised thing is lit
/// from above.
List<BoxShadow> raisedShadow(AppColors c, {double lift = 1}) => [
  BoxShadow(color: c.shadow, blurRadius: 5 * lift, offset: Offset(0, 2 * lift)),
];

/// Linen cloth, for the page.
BoxDecoration linenDecoration(AppColors c) =>
    BoxDecoration(color: c.background, image: Textures.image(Textures.linen));

/// A sheet of paper lying on the linen.
BoxDecoration paperDecoration(
  AppColors c, {
  bool tint = false,
  double radius = RohabShape.card,
  bool shadow = true,
}) => BoxDecoration(
  color: tint ? c.accentSoft : c.surface,
  borderRadius: BorderRadius.circular(radius),
  border: Border.all(
    color: tint ? c.accent.withValues(alpha: 0.45) : c.divider,
    width: RohabShape.border,
  ),
  image: Textures.image(Textures.paper),
  boxShadow: shadow ? raisedShadow(c) : null,
);

/// Blue leather, for the title bar.
BoxDecoration leatherDecoration(AppColors c) =>
    BoxDecoration(color: c.leather, image: Textures.image(Textures.leather));

/// Brushed steel, for the tab bar.
BoxDecoration steelDecoration(AppColors c) =>
    BoxDecoration(color: c.steel, image: Textures.image(Textures.metal));

/// Paints the light edge and the glossy split of a raised surface (or the
/// opposite, when [pressed]). Used for buttons, tiles and gauge fills. It
/// only adds translucent light and shade, so it works over any base colour.
class BevelPainter extends CustomPainter {
  const BevelPainter({
    this.radius = RohabShape.radius,
    this.pressed = false,
    this.flat = false,
    this.gloss = true,
  });

  final double radius;

  /// Pushed in: shade at the top, light at the bottom.
  final bool pressed;

  /// Disabled: no light or shade at all.
  final bool flat;

  /// The lighter upper half that gives the classic glossy button.
  final bool gloss;

  @override
  void paint(Canvas canvas, Size size) {
    if (flat || size.isEmpty) return;
    final outer = RRect.fromRectAndRadius(
      Offset.zero & size,
      Radius.circular(radius),
    );
    canvas.save();
    canvas.clipRRect(outer);

    if (pressed) {
      // Sunk: darker overall, with a shadow cast from the top edge.
      canvas.drawRect(
        Offset.zero & size,
        Paint()..color = const Color(0x26000000),
      );
      canvas.drawRect(
        Rect.fromLTWH(0, 0, size.width, 7),
        Paint()
          ..shader = const LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: [Color(0x55000000), Color(0x00000000)],
          ).createShader(Rect.fromLTWH(0, 0, size.width, 7)),
      );
      canvas.drawLine(
        Offset(radius * 0.5, size.height - 0.5),
        Offset(size.width - radius * 0.5, size.height - 0.5),
        Paint()
          ..color = const Color(0x55FFFFFF)
          ..strokeWidth = 1,
      );
    } else {
      if (gloss) {
        // Hard split: the top half catches the light.
        canvas.drawRect(
          Rect.fromLTWH(0, 0, size.width, size.height / 2),
          Paint()..color = const Color(0x2EFFFFFF),
        );
        canvas.drawRect(
          Rect.fromLTWH(0, size.height / 2, size.width, size.height / 2),
          Paint()..color = const Color(0x14000000),
        );
      }
      // Bright edge along the top, dark edge along the bottom.
      canvas.drawLine(
        Offset(radius * 0.5, 1),
        Offset(size.width - radius * 0.5, 1),
        Paint()
          ..color = const Color(0x99FFFFFF)
          ..strokeWidth = 1.5,
      );
      canvas.drawLine(
        Offset(radius * 0.5, size.height - 0.5),
        Offset(size.width - radius * 0.5, size.height - 0.5),
        Paint()
          ..color = const Color(0x40000000)
          ..strokeWidth = 1,
      );
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(BevelPainter old) =>
      old.radius != radius ||
      old.pressed != pressed ||
      old.flat != flat ||
      old.gloss != gloss;
}

/// A beveled, raised tile: the base for icon badges and other small
/// controls that are not buttons.
class RaisedTile extends StatelessWidget {
  const RaisedTile({
    super.key,
    required this.color,
    required this.child,
    this.size,
    this.radius = RohabShape.radius,
    this.edge,
  });

  final Color color;
  final Widget child;
  final double? size;
  final double radius;
  final Color? edge;

  @override
  Widget build(BuildContext context) {
    final c = context.colors;
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        color: color,
        borderRadius: BorderRadius.circular(radius),
        border: Border.all(
          color: edge ?? Color.lerp(color, const Color(0xFF000000), 0.35)!,
          width: 1,
        ),
        boxShadow: raisedShadow(c, lift: 0.6),
      ),
      child: CustomPaint(
        painter: BevelPainter(radius: radius),
        child: Center(child: child),
      ),
    );
  }
}

/// Paints a stitched seam: a row of short dashes, like thread on leather.
class StitchPainter extends CustomPainter {
  const StitchPainter(this.color);

  final Color color;

  @override
  void paint(Canvas canvas, Size size) {
    final p = Paint()
      ..color = color
      ..strokeWidth = 1.5
      ..strokeCap = StrokeCap.round;
    const dash = 6.0;
    const gap = 4.0;
    final y = size.height / 2;
    for (var x = 4.0; x < size.width - dash; x += dash + gap) {
      canvas.drawLine(Offset(x, y), Offset(x + dash, y), p);
    }
  }

  @override
  bool shouldRepaint(StitchPainter old) => old.color != color;
}

/// Button look shared by the filled, outlined and text buttons: a beveled
/// face that sinks (and loses its shadow) when pressed, with letterpress
/// text. The base colour comes from the button's own style, so a red STOP
/// button and a blue primary button are both beveled the same way.
ButtonStyle raised(ButtonStyle base, {required bool darkText}) {
  return base.copyWith(
    elevation: WidgetStateProperty.resolveWith(
      (s) => s.contains(WidgetState.pressed) || s.contains(WidgetState.disabled)
          ? 0.0
          : 3.0,
    ),
    shadowColor: const WidgetStatePropertyAll(Color(0x80102030)),
    overlayColor: const WidgetStatePropertyAll(Color(0x00000000)),
    splashFactory: NoSplash.splashFactory,
    backgroundBuilder: (context, states, child) => CustomPaint(
      painter: BevelPainter(
        pressed: states.contains(WidgetState.pressed),
        flat: states.contains(WidgetState.disabled),
      ),
      child: child,
    ),
    foregroundBuilder: (context, states, child) => Transform.translate(
      offset: states.contains(WidgetState.pressed)
          ? const Offset(0, 1)
          : Offset.zero,
      child: DefaultTextStyle.merge(
        style: TextStyle(
          shadows: [
            darkText
                ? const Shadow(color: Color(0xCCFFFFFF), offset: Offset(0, 1))
                : const Shadow(color: Color(0x80000000), offset: Offset(0, -1)),
          ],
        ),
        child: child!,
      ),
    ),
  );
}

/// One option of a choice row (text size, exercise, pain score). The chosen
/// option is pressed in and blue, like a lit toggle; the others stand out
/// as silver buttons. Put an [InkWell] inside as the [child].
class ChoiceMaterial extends StatelessWidget {
  const ChoiceMaterial({
    super.key,
    required this.selected,
    required this.child,
  });

  final bool selected;
  final Widget child;

  @override
  Widget build(BuildContext context) {
    final c = context.colors;
    const radius = BorderRadius.all(Radius.circular(RohabShape.radius));
    return Material(
      color: selected ? c.accent : c.silver,
      elevation: selected ? 0 : 2,
      shadowColor: const Color(0x80102030),
      shape: RoundedRectangleBorder(
        borderRadius: radius,
        side: BorderSide(
          color: selected
              ? Color.lerp(c.accent, const Color(0xFF000000), 0.45)!
              : c.silverEdge,
        ),
      ),
      clipBehavior: Clip.antiAlias,
      child: CustomPaint(
        painter: BevelPainter(pressed: selected),
        child: child,
      ),
    );
  }
}
